exec_create: sh -ec psql -X --username "$POSTGRES_USER" --dbname "$POSTGRES_DB" --csv --command "$1" capacity 
    select current_setting('server_version_num') as server_version_num;
    select extversion from pg_extension where extname = 'vector';
    select name, setting, unit, source
    from pg_settings
    where name in (
      'shared_buffers', 'work_mem', 'maintenance_work_mem', 'autovacuum_work_mem',
      'temp_buffers', 'max_connections', 'wal_buffers', 'effective_cache_size',
      'max_worker_processes', 'max_parallel_workers', 'max_parallel_workers_per_gather',
      'huge_pages', 'jit'
    )
    order by name;

